func maxDepth(root *TreeNode) int {
	// 节点为空，高度为 0
	if root == nil {
		return 0
	}
	// 递归计算左子树的最大深度
	leftHeight := maxDepth(root.Left)
	// 递归计算右子树的最大深度
	rightHeight := maxDepth(root.Right)
	// 二叉树的最大深度 = 子树的最大深度 + 1（1 是根节点）
	if leftHeight > rightHeight {
		return leftHeight + 1
	}
	return rightHeight + 1
}

