func maxDepth(root *TreeNode) int {
	if root == nil {
		return 0
	}
	// 初始化队列
	queue := []*TreeNode{root}
	depth := 0
	// 当队列不为空
	for len(queue) > 0 {
		// 当前层的节点数
		n := len(queue)
		// 弹出当前层的所有节点，并将所有子节点入队列
		for i := 0; i < n; i++ {
			node := queue[0]
			queue = queue[1:]
			if node.Left != nil {
				queue = append(queue, node.Left)
			}
			if node.Right != nil {
				queue = append(queue, node.Right)
			}
		}
		depth++
	}
	// 二叉树最大层次即为二叉树最深深度
	return depth
}

